import { describe, expect, test } from "bun:test";

import { parseSessionCookies } from "../../src/session/session.parse.ts";

/** Every value here is invented; no real cookie ever belongs in a fixture. */
const NETSCAPE = [
  "# Netscape HTTP Cookie File",
  "# This file was generated by a cookie exporter.",
  "",
  "grafana.example.test\tTRUE\t/\tTRUE\t2000000000\tsession_id\tvalue-1",
  "#HttpOnly_grafana.example.test\tTRUE\t/api\tFALSE\t0\tcsrf\tvalue-2",
  ".kibana.example.test\tFALSE\t\tFALSE\t1900000000\tsid\tvalue-3",
].join("\n");

function expectOk(result: ReturnType<typeof parseSessionCookies>) {
  if (!result.ok) throw new Error(`expected ok, got ${result.reason}`);
  return result;
}

describe("parseSessionCookies on Netscape cookies.txt", () => {
  test("reads every well-formed row and reports the format", () => {
    const result = expectOk(parseSessionCookies(NETSCAPE));
    expect(result.format).toBe("netscape");
    expect(result.cookies).toHaveLength(3);
    expect(result.skipped).toBe(0);
  });

  test("keeps the seven columns in the right places", () => {
    const [first] = expectOk(parseSessionCookies(NETSCAPE)).cookies;
    expect(first).toEqual({
      name: "session_id",
      value: "value-1",
      domain: "grafana.example.test",
      path: "/",
      secure: true,
      httpOnly: false,
      expires: 2000000000,
    });
  });

  test("treats #HttpOnly_ as a domain prefix, not a comment", () => {
    const cookies = expectOk(parseSessionCookies(NETSCAPE)).cookies;
    const csrf = cookies.find((cookie) => cookie.name === "csrf");
    expect(csrf?.httpOnly).toBe(true);
    expect(csrf?.domain).toBe("grafana.example.test");
  });

  test("turns expires 0 into a session cookie", () => {
    const cookies = expectOk(parseSessionCookies(NETSCAPE)).cookies;
    expect(cookies.find((cookie) => cookie.name === "csrf")?.expires).toBe(null);
  });

  test("defaults an empty path column to /", () => {
    const cookies = expectOk(parseSessionCookies(NETSCAPE)).cookies;
    expect(cookies.find((cookie) => cookie.name === "sid")?.path).toBe("/");
  });

  test("skips comments and blank lines without counting them as damage", () => {
    const result = expectOk(
      parseSessionCookies(
        [
          "# a comment",
          "   ",
          "",
          "a.example.test\tTRUE\t/\tFALSE\t0\tname-1\tvalue-1",
        ].join("\n"),
      ),
    );
    expect(result.cookies).toHaveLength(1);
    expect(result.skipped).toBe(0);
  });

  test("skips a broken row and keeps the good ones around it", () => {
    const result = expectOk(
      parseSessionCookies(
        [
          "a.example.test\tTRUE\t/\tFALSE\t0\tname-1\tvalue-1",
          "not\tenough\tcolumns",
          "\tTRUE\t/\tFALSE\t0\tname-2\tvalue-2",
          "b.example.test\tTRUE\t/\tFALSE\t0\t\tvalue-3",
          "c.example.test\tTRUE\t/\tFALSE\t0\tname-4\tvalue-4",
        ].join("\n"),
      ),
    );
    expect(result.cookies.map((cookie) => cookie.name)).toEqual([
      "name-1",
      "name-4",
    ]);
    expect(result.skipped).toBe(3);
  });

  test("accepts a row whose value column is absent as an empty value", () => {
    const result = expectOk(
      parseSessionCookies("a.example.test\tTRUE\t/\tFALSE\t0\tname-1"),
    );
    expect(result.cookies[0]?.value).toBe("");
  });

  test("reads a non-numeric expiry as a session cookie rather than dropping the row", () => {
    const result = expectOk(
      parseSessionCookies("a.example.test\tTRUE\t/\tFALSE\tnever\tname-1\tvalue-1"),
    );
    expect(result.cookies[0]?.expires).toBe(null);
  });
});

describe("parseSessionCookies on extension JSON", () => {
  const JSON_EXPORT = JSON.stringify([
    {
      name: "session_id",
      value: "value-1",
      domain: ".grafana.example.test",
      path: "/",
      secure: true,
      httpOnly: true,
      expirationDate: 1900000000.6543,
    },
    {
      name: "csrf",
      value: "value-2",
      domain: "kibana.example.test",
      path: "/app",
      secure: false,
      httpOnly: false,
      session: true,
      expirationDate: 1900000000,
    },
    {
      name: "legacy",
      value: "value-3",
      domain: "prometheus.example.test",
      path: "/",
      expires: 1800000000,
    },
  ]);

  test("reads the array and reports the format", () => {
    const result = expectOk(parseSessionCookies(JSON_EXPORT));
    expect(result.format).toBe("json");
    expect(result.cookies).toHaveLength(3);
    expect(result.skipped).toBe(0);
  });

  test("floors a float expirationDate to whole seconds", () => {
    const result = expectOk(parseSessionCookies(JSON_EXPORT));
    expect(result.cookies[0]?.expires).toBe(1900000000);
  });

  test("lets session: true win over a present expirationDate", () => {
    const result = expectOk(parseSessionCookies(JSON_EXPORT));
    expect(result.cookies[1]?.expires).toBe(null);
  });

  test("falls back to the expires field and to safe defaults", () => {
    const result = expectOk(parseSessionCookies(JSON_EXPORT));
    expect(result.cookies[2]).toEqual({
      name: "legacy",
      value: "value-3",
      domain: "prometheus.example.test",
      path: "/",
      secure: false,
      httpOnly: false,
      expires: 1800000000,
    });
  });

  test("skips entries that are not cookie-shaped and keeps the rest", () => {
    const result = expectOk(
      parseSessionCookies(
        JSON.stringify([
          "not an object",
          null,
          { value: "value-1", domain: "a.example.test" },
          { name: "name-2", domain: "" },
          { name: "name-3", value: "value-3", domain: "b.example.test" },
        ]),
      ),
    );
    expect(result.cookies.map((cookie) => cookie.name)).toEqual(["name-3"]);
    expect(result.skipped).toBe(4);
  });
});

describe("parseSessionCookies failures", () => {
  test("reports empty-file for whitespace only", () => {
    expect(parseSessionCookies("   \n\t\n")).toEqual({
      ok: false,
      reason: "empty-file",
    });
  });

  test("reports unrecognised-format for broken JSON", () => {
    expect(parseSessionCookies('[{"name": "a",}')).toEqual({
      ok: false,
      reason: "unrecognised-format",
    });
  });

  test("reports unrecognised-format for JSON that is not an array", () => {
    expect(parseSessionCookies('{"cookies": []}')).toEqual({
      ok: false,
      reason: "unrecognised-format",
    });
  });

  test("reports unrecognised-format for text with no tabs at all", () => {
    expect(parseSessionCookies("some other export\nwith no tabs")).toEqual({
      ok: false,
      reason: "unrecognised-format",
    });
  });

  test("reports no-valid-cookies for an empty JSON array", () => {
    expect(parseSessionCookies("[]")).toEqual({
      ok: false,
      reason: "no-valid-cookies",
    });
  });

  test("reports no-valid-cookies when every Netscape row is broken", () => {
    expect(parseSessionCookies("a\tb\tc\nd\te\tf")).toEqual({
      ok: false,
      reason: "no-valid-cookies",
    });
  });
});
